package com.ruoyi.paicli.service;

import com.ruoyi.paicli.domain.*;
import org.springframework.transaction.annotation.Transactional;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.*;

/** PAI原文件与已明确提供的imports由中心登记；不会扫描服务端或Runner目录。 */
public class PcProjectRuleService {
    public static final List<String> LAYERS=List.of("USER_PAI","ROOT_PAI","PAICLI_PAI","LOCAL_PAI","PAICLI_LOCAL_PAI");
    private final PcStore store;private final PcAccess access;private final PcIdempotency idem;private final PcEvidence evidence;private final PcArtifactService artifacts;
    public PcProjectRuleService(PcStore s,PcAccess a,PcIdempotency i,PcEvidence e,PcArtifactService ar){store=s;access=a;idem=i;evidence=e;artifacts=ar;}
    public static boolean isRule(PcRecord row,Map<String,Object> data){return Set.of("PROJECT_RULE","POLICY").contains(row.getKind())||Set.of("PROJECT_MEMORY","IMPORTED_PROJECT_RULE","PAI_RULE").contains(PcJson.text(data,"source"));}
    public static List<PcRecord> rootRules(PcStore store,long workspace){return store.mapper.list(PcTable.MEMORY,workspace,null,null,null).stream().filter(r->{Map<String,Object> p=store.data(r);return r.getWorkspaceId()==null&&isRule(r,p)&&!Set.of("FROZEN","DELETED","REPLACED","REVOKED_IMPORT").contains(r.getState())&&(PcJson.text(p,"layer").equals("ROOT_PAI")||PcJson.text(p,"layer").isBlank());}).toList();}
    public static Map<String,Object> initArguments(PcStore store,long workspace,Map<String,Object> input){boolean force=Boolean.TRUE.equals(input.get("force"));List<PcRecord> rules=rootRules(store,workspace);if(!force&&!rules.isEmpty())throw PcException.conflict("中心已有ROOT_PAI项目规则，请明确force并批准目标版本替换");Map<String,Object> versions=new LinkedHashMap<>();for(PcRecord row:rules)versions.put(String.valueOf(row.getId()),row.getVersion());return Map.of("force",force,"rootRuleVersions",versions,"ruleLocation","CENTER_ROOT_PAI");}
    public static void validateInit(PcStore store,long workspace,Map<String,Object> args){Map<String,Object> frozen=PcJson.object(args,"rootRuleVersions"),actual=PcJson.object(initArguments(store,workspace,args),"rootRuleVersions");if(!frozen.keySet().equals(actual.keySet()))throw PcException.conflict("初始化目标ROOT_PAI集合变化，请重新批准");for(String id:frozen.keySet())if(PcJson.number(frozen,id)!=PcJson.number(actual,id))throw PcException.conflict("初始化目标ROOT_PAI版本变化，请重新批准");}
    public List<Map<String,Object>> list(long user,Long workspace){if(workspace!=null)access.directory(workspace,user,false);return store.mapper.visible(PcTable.MEMORY,user,workspace,false).stream().filter(r->isRule(r,store.data(r))).map(r->view(r,false,user)).toList();}
    public Map<String,Object> get(long user,long id,boolean raw){PcRecord row=access.resource(PcTable.MEMORY,id,user,false,false);if(!isRule(row,store.data(row)))throw PcException.invalid("对象不是PAI规则");return view(row,raw,user);}
    private Map<String,Object> view(PcRecord row,boolean raw,long user){Map<String,Object> value=store.view(row);value.put("canEdit",Objects.equals(row.getOwnerId(),user)&&(row.getDirectoryContextId()==null||"OWNER".equals(access.owner(row.getDirectoryContextId(),user))));if(value.get("contentArtifactId")!=null)value.put("contentArtifact",sourceMetadata(row,value));if(value.get("imports") instanceof List<?> imports)value.put("imports",imports.stream().map(v->{Map<String,Object> item=new LinkedHashMap<>();if(v instanceof Map<?,?> m)m.forEach((k,x)->{if(raw||!k.toString().equals("content"))item.put(k.toString(),x);});if(item.get("contentArtifactId")!=null)item.put("contentArtifact",sourceMetadata(row,item));return item;}).toList());if(!raw){value.remove("content");value.remove("fact");value.remove("originalContent");value.remove("resolvedContent");}return value;}
    private Map<String,Object> sourceMetadata(PcRecord rule,Map<String,Object> source){PcRecord artifact=store.require(PcTable.ARTIFACT,PcJson.number(source,"contentArtifactId"),false);Map<String,Object> data=store.data(artifact);if(!artifact.getKind().equals("PAI_SOURCE")||!"PAI_SOURCE".equals(data.get("purpose"))||!"UTF-8".equals(data.get("encoding"))||!Objects.equals(artifact.getOwnerId(),rule.getOwnerId())||rule.getDirectoryContextId()!=null&&!Objects.equals(artifact.getDirectoryContextId(),rule.getDirectoryContextId())||!Objects.equals(data.get("sha256"),source.get("sha256")))throw PcException.deny("PAI原文引用用途、归属或SHA与已登记来源不同");Map<String,Object> result=new LinkedHashMap<>();result.put("id",artifact.getId().toString());result.put("ownerId",artifact.getOwnerId().toString());if(artifact.getDirectoryContextId()!=null)result.put("directoryContextId",artifact.getDirectoryContextId().toString());for(String field:List.of("sha256","size","fileName","purpose"))result.put(field,data.get(field));return result;}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> save(long user,String key,long version,Map<String,Object> input){return idem.run("user:"+user+":project-rule",key,Map.of("version",version,"input",input),()->{
        String scope=PcJson.text(input,"scope"),layer=PcJson.text(input,"layer");if(!Set.of("PERSONAL","PROJECT").contains(scope)||!LAYERS.contains(layer)||scope.equals("PERSONAL")!=layer.equals("USER_PAI"))throw PcException.invalid("PAI scope与来源层不一致");Long workspace=scope.equals("PERSONAL")?null:PcJson.number(input,"directoryContextId");if(workspace!=null){access.admin(workspace,user);access.directory(workspace,user,true);}else{String lockKey="memory-scope:user:"+user;if(store.mapper.findKey(PcTable.MEMORY,lockKey,true)==null)store.insert(PcTable.MEMORY,null,user,null,null,null,"SCOPE_LOCK","ACTIVE",lockKey,Map.of());}String path=PcPromptService.normalize(PcJson.text(input,"sourcePath"));String original=content(user,workspace,input);if(PcSecretPolicy.contains(original))throw PcException.invalid("PAI正文不能携带明文凭证");Map<String,String> sources=new LinkedHashMap<>();sources.put(path,original);long sourceBytes=original.getBytes(StandardCharsets.UTF_8).length;List<Map<String,Object>> imports=new ArrayList<>();if(input.get("imports")!=null){if(!(input.get("imports") instanceof List<?> list)||list.size()>200)throw PcException.invalid("PAI imports须为不超过200项的明确来源");for(Object value:list){if(!(value instanceof Map<?,?> map))throw PcException.invalid("PAI import须为对象");Map<String,Object> item=new LinkedHashMap<>();map.forEach((k,v)->item.put(k.toString(),v));String imported=PcPromptService.normalize(PcJson.text(item,"path")),text=content(user,workspace,item);sourceBytes+=text.getBytes(StandardCharsets.UTF_8).length;if(sourceBytes>128L*1024*1024)throw new PcException(413,"PC_PAI_SOURCE_LIMIT","PAI及imports原文累计超过128MiB，请拆分来源登记");if(sources.putIfAbsent(imported,text)!=null)throw PcException.invalid("PAI来源路径重复");if(PcSecretPolicy.contains(text))throw PcException.invalid("PAI import不能携带明文凭证");Map<String,Object> stored=new LinkedHashMap<>();stored.put("path",imported);stored.put("sha256",PcJson.digest(text));if(item.get("contentArtifactId")!=null)stored.put("contentArtifactId",item.get("contentArtifactId").toString());else stored.put("content",text);imports.add(stored);}}
        List<String> warnings=new ArrayList<>();String resolved=resolve(path,sources,new HashSet<>(),0,warnings).strip();String hash=PcJson.digest(original);if(input.get("sha256")!=null&&!hash.equals(input.get("sha256")))throw PcException.conflict("PAI原内容SHA不一致");Map<String,Object> data=new LinkedHashMap<>();data.put("scope",scope);data.put("layer",layer);data.put("sourcePath",path);data.put("source","PAI_RULE");data.put("content",resolved);data.put("fact",resolved);data.put("resolvedContent",resolved);data.put("sha256",hash);data.put("encoding","UTF-8");data.put("resolvedHash",PcJson.digest(resolved));data.put("imports",imports);data.put("warnings",warnings);data.put("enabled",!Boolean.FALSE.equals(input.get("enabled")));data.put("registeredLayer",true);if(input.get("contentArtifactId")!=null)data.put("contentArtifactId",input.get("contentArtifactId").toString());else data.put("originalContent",original);String unique="pai:"+Objects.toString(workspace,"user:"+user)+":"+layer;PcRecord row;if(input.get("id")!=null){row=access.resource(PcTable.MEMORY,PcJson.number(input,"id"),user,false,true);store.version(row,version);Map<String,Object> prior=store.data(row);boolean imported=prior.get("importBatchId")!=null&&row.getUniqueKey()!=null&&row.getUniqueKey().startsWith("import:");boolean registeredRow=Boolean.TRUE.equals(prior.get("registeredLayer"));if(!isRule(row,prior)||!Objects.equals(row.getDirectoryContextId(),workspace)||!Objects.equals(row.getOwnerId(),user)||!unique.equals(row.getUniqueKey())&&!imported&&!registeredRow||(imported||registeredRow)&&!layer.equals(PcJson.text(prior,"layer")))throw PcException.deny("PAI更新不能改变scope/来源层/owner");if(registered(workspace,user,layer,row.getId()))throw PcException.conflict("该PAI层已有正式规则，请明确版本替换");if(imported){row.setKind("PROJECT_RULE");for(String field:List.of("importBatchId","legacyId","sourceFingerprint","legacyPayloadHash","legacyOccurredAt","legacyOwnerId","sourceSha256","variant","relativePath"))if(prior.containsKey(field))data.put(field,prior.get(field));}row.setState(Boolean.TRUE.equals(data.get("enabled"))?"VERIFIED":"DISABLED");store.save(PcTable.MEMORY,row,data);}else{if(version!=0||store.mapper.findKey(PcTable.MEMORY,unique,true)!=null||registered(workspace,user,layer,null))throw PcException.conflict("该PAI来源层已登记，请按版本更新");row=store.insert(PcTable.MEMORY,workspace,user,null,null,null,"PROJECT_RULE",Boolean.TRUE.equals(data.get("enabled"))?"VERIFIED":"DISABLED",unique,data);}store.insert(PcTable.MEMORY_VERSION,workspace,user,row.getId(),null,null,"PROJECT_RULE_VERSION","APPENDED",null,data);evidence.audit(workspace,user,null,null,"PAI_RULE_SAVE","ACCEPTED",Map.of("id",row.getId(),"sha256",hash,"resolvedHash",data.get("resolvedHash")));return view(row,false,user);
    });}
    private boolean registered(Long workspace,long user,String layer,Long except){return store.mapper.list(PcTable.MEMORY,workspace,workspace==null?user:null,null,null).stream().filter(r->r.getWorkspaceId()==null&&Objects.equals(r.getOwnerId(),user)&&Objects.equals(r.getDirectoryContextId(),workspace)&&!Objects.equals(r.getId(),except)&&!Set.of("FROZEN","DELETED","REVOKED_IMPORT","REPLACED").contains(r.getState())).anyMatch(r->{Map<String,Object> p=store.data(r);return layer.equals(p.get("layer"))&&(Boolean.TRUE.equals(p.get("registeredLayer"))||r.getUniqueKey()!=null&&r.getUniqueKey().startsWith("pai:"));});}
    private String content(long user,Long workspace,Map<String,Object> input){String text;if(input.get("contentArtifactId")!=null){PcRecord artifact=access.resource(PcTable.ARTIFACT,PcJson.number(input,"contentArtifactId"),user,true,false);if(!Objects.equals(workspace,artifact.getDirectoryContextId())&&workspace!=null)throw PcException.deny("PAI来源产物不属于目录");Map<String,Object> metadata=store.data(artifact);if(!"PAI_SOURCE".equals(artifact.getKind())||!"PAI_SOURCE".equals(metadata.get("purpose"))||!"UTF-8".equals(metadata.get("encoding")))throw PcException.deny("PAI来源必须使用PAI_SOURCE严格UTF-8产物用途");var file=artifacts.content(user,artifact.getId());if(file.size()>50L*1024*1024)throw PcException.invalid("PAI来源文件超出50MiB");try{text=Files.readString(file.file(),StandardCharsets.UTF_8);}catch(java.io.IOException failure){throw PcException.invalid("PAI来源文件不是可读UTF-8文本");}}else{text=PcJson.text(input,"content");if(text.getBytes(StandardCharsets.UTF_8).length>1024*1024)throw new PcException(413,"PC_PAI_ARTIFACT_REQUIRED","超过1MiB的PAI来源请上传正式产物引用");}if(text.isBlank())throw PcException.invalid("PAI来源内容为空");return text;}
    private static String resolve(String path,Map<String,String> sources,Set<String> stack,int depth,List<String> warnings){if(depth>3){warnings.add("跳过超过3层的import："+path);return "";}if(!stack.add(path)){warnings.add("跳过循环import："+path);return "";}String source=sources.get(path);if(source==null){warnings.add("未明确提供import来源："+path);stack.remove(path);return "";}StringBuilder result=new StringBuilder();for(String line:source.split("\\R",-1)){String trimmed=line.strip();if(trimmed.startsWith("@")&&trimmed.length()>1&&!trimmed.contains(" ")&&!trimmed.substring(1).startsWith("/")&&!trimmed.contains("..")){String parent=path.contains("/")?path.substring(0,path.lastIndexOf('/')+1):"";String reference;try{reference=PcPromptService.normalize(parent+trimmed.substring(1));}catch(PcException invalid){warnings.add("跳过非法import："+path);continue;}String imported=resolve(reference,sources,stack,depth+1,warnings).strip();if(!imported.isBlank())result.append(imported).append('\n');}else result.append(line).append('\n');if(result.length()>=24000){result.setLength(24000);warnings.add("派生规则按24000字符预算截断；原文仍保留");break;}}stack.remove(path);return result.toString();}
    private static List<Map<String,Object>> safeImports(Map<String,Object> data){if(!(data.get("imports") instanceof List<?> values))return List.of();return values.stream().map(value->{Map<String,Object> result=new LinkedHashMap<>();if(value instanceof Map<?,?> map)for(String field:List.of("path","sha256","contentArtifactId"))if(map.get(field)!=null)result.put(field,map.get(field));return result;}).toList();}
    public static Map<String,Object> forTask(PcStore store,PcRecord task){List<PcRecord> rows=new ArrayList<>();rows.addAll(store.mapper.list(PcTable.MEMORY,null,task.getOwnerId(),null,"VERIFIED").stream().filter(r->r.getDirectoryContextId()==null).toList());rows.addAll(store.mapper.list(PcTable.MEMORY,task.getDirectoryContextId(),null,null,"VERIFIED"));rows=rows.stream().filter(r->r.getWorkspaceId()==null&&Objects.equals(r.getOwnerId(),task.getOwnerId())&&isRule(r,store.data(r))&&!Boolean.FALSE.equals(store.data(r).get("enabled"))&&(PcJson.text(store.data(r),"layer").isBlank()||LAYERS.contains(PcJson.text(store.data(r),"layer")))).sorted(Comparator.<PcRecord>comparingInt(r->{String layer=PcJson.text(store.data(r),"layer");if(layer.isBlank())layer=r.getDirectoryContextId()==null?"USER_PAI":"ROOT_PAI";return LAYERS.indexOf(layer);}).thenComparingLong(PcRecord::getId)).toList();StringBuilder merged=new StringBuilder();List<Map<String,Object>> provenance=new ArrayList<>();for(PcRecord row:rows){Map<String,Object> data=store.data(row);String content=PcJson.text(data,"resolvedContent");if(content.isBlank())content=PcJson.text(data,"content");String path=PcJson.text(data,"sourcePath");if(path.isBlank())path=row.getDirectoryContextId()==null?"user/PAI.md":"PAI.md";merged.append("### ").append(path).append("\n\n").append(content).append("\n\n");provenance.add(Map.of("id",String.valueOf(row.getId()),"version",row.getVersion(),"scope",row.getDirectoryContextId()==null?"PERSONAL":"PROJECT","sourcePath",path,"layer",data.getOrDefault("layer",row.getDirectoryContextId()==null?"USER_PAI":"ROOT_PAI"),"sha256",data.getOrDefault("sha256",PcJson.digest(content)),"resolvedHash",PcJson.digest(content),"imports",safeImports(data)));if(merged.length()>=24000){merged.setLength(23920);merged.append("\n\n[PAI.md 内容已按24000字符预算截断；原始来源仍保留]");break;}}return Map.of("projectMemoryContext",merged.isEmpty()?"":"## PAI.md 项目记忆\n\n"+merged,"projectRuleSources",provenance);}
}
